begin;
alter table prizes drop constraint if exists prizes_wheel_index_check;
alter table prizes add constraint prizes_wheel_index_check check (wheel_index between 0 and 6);
do $$declare c campaigns;p prizes;existing_units int;max_unit int;changed boolean:=false;begin select * into c from campaigns where code='JLPT_SPIN_2026' for update;if not found then raise exception 'CAMPAIGN_NOT_FOUND';end if;select * into p from prizes where campaign_id=c.id and code='JLPT_MATERIALS_N5_N1' for update;if not found then insert into prizes(campaign_id,code,name,total_qty,wheel_index,display_order,active)values(c.id,'JLPT_MATERIALS_N5_N1','Trọn bộ tài liệu luyện thi JLPT N5-N1 mới nhất',30,6,6,true)returning * into p;changed:=true;else if p.total_qty<>30 or p.name<>'Trọn bộ tài liệu luyện thi JLPT N5-N1 mới nhất' or p.wheel_index<>6 or p.display_order<>6 or not p.active then update prizes set name='Trọn bộ tài liệu luyện thi JLPT N5-N1 mới nhất',total_qty=30,wheel_index=6,display_order=6,active=true where id=p.id returning * into p;changed:=true;end if;end if;select count(*)::int into existing_units from prize_units where prize_id=p.id;if existing_units>30 then raise exception 'MATERIAL_PRIZE_HAS_TOO_MANY_UNITS';end if;if existing_units<30 then select coalesce(max(unit_no),0)into max_unit from prize_units where campaign_id=c.id;insert into prize_units(campaign_id,prize_id,unit_no)select c.id,p.id,max_unit+x from generate_series(1,30-existing_units)x;changed:=true;end if;update campaigns set total_inventory=(select sum(total_qty)::int from prizes where campaign_id=c.id),inventory_version=inventory_version+(case when changed then 1 else 0 end)where id=c.id;if(select count(*)from prize_units where prize_id=p.id)<>30 then raise exception 'MATERIAL_UNIT_ASSERTION_FAILED';end if;if(select sum(total_qty)from prizes where campaign_id=c.id)<>80 then raise exception 'CAMPAIGN_TOTAL_ASSERTION_FAILED';end if;end$$;
commit;
